/**
 * Full E2E smoke tests for ALL 438 calculator service scenarios.
 *
 * Each test creates an estimate via EstimateBuilder using the correct
 * service key from the manifest, exports it to calculator.aws, opens the
 * URL in Playwright, and verifies the engine renders a non-zero cost.
 *
 * Run all (~75 min):  node --test test/smoke-all-services.test.js
 * Run one:            node --test test/smoke-all-services.test.js --test-name-pattern="nat_gateway"
 * Run group:          node --test test/smoke-all-services.test.js --test-name-pattern="rds"
 */
const { describe, it, before } = require('node:test');
const assert = require('node:assert/strict');
const EstimateBuilder = require('../lib/estimate-builder');

let chromium;
try { chromium = require('playwright').chromium; } catch { chromium = null; }

const RENDER_WAIT = 6000;

async function getEstimateCost(url) {
  if (!chromium) throw new Error('Playwright not installed');
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(RENDER_WAIT);
  const amounts = await page.locator('[class*="amount"]').allTextContents();
  await browser.close();
  const monthly = amounts.find(a => a.includes('USD') && !a.startsWith('0.00'));
  if (!monthly) return 0;
  return parseFloat(monthly.replace(/[^0-9.]/g, ''));
}


