describe('e2e: all 438 service scenarios', () => {
  before(() => {
    if (!chromium) {
      console.log('  ⚠ Playwright not installed — run: npx playwright install chromium');
    }
  });

  for (const testCase of ALL_CASES) {
    it(`${testCase.id}: ${testCase.serviceName}`, async (t) => {
      if (!chromium) return t.skip('Playwright not installed');

      const eb = new EstimateBuilder(`E2E: ${testCase.scenario.substring(0, 50)}`);
      const config = { region: testCase.region, description: testCase.scenario, ...testCase.config };
      eb.addService(testCase.serviceKey, config);

      let result;
      try {
        result = await eb.export();
      } catch (err) {
        return t.skip(`Export failed: ${err.message.substring(0, 100)}`);
      }

      assert.ok(result.shareableUrl, 'should export a URL');

      const cost = await getEstimateCost(result.shareableUrl);

      if (cost > 0) {
        console.log(`    ✓ $${cost.toFixed(2)}`);
      } else {
        console.log(`    ⚠ $0.00 (free tier or rehydration limitation)`);
      }

      // Cases flagged expectNonZero MUST price above expectMin (default 0). This
      // guards against silent $0 regressions like the FSx for Lustre storage bug
      // where a friendly label ("storageCapacity") never mapped to the real field
      // id (persistent_generated_0) and the columnFormIPM row was absent, so the
      // engine priced storage at $0 while the export still succeeded.
      if (testCase.expectNonZero) {
        const min = testCase.expectMin || 0;
        assert.ok(cost > min, `${testCase.id} should price above $${min}, got $${cost.toFixed(2)}`);
      }
    });
  }
});
